39	    'the template still tells the filer to block on the PR — the field that invited the premature file');
40	});
41	
42	// The verification is AUTOMATIC end to end: the filed check must be one an
43	// unattended run can read, and a person enters only where no such read exists.
44	test('the check is automatic by construction, and a human is the last resort', () => {
45	  assert.match(skill, /unattended[\s*]+run can make/i,
46	    'nothing requires Verify: to be automatically checkable');
47	  assert.match(skill, /no automatic check/i,
48	    'the skill never bounds when a person may be asked at all');
49	});

